SELECT s.symbol, COUNT(*) AS n, AVG(s.atr_percent) AS avg_atr_pct, MIN(s.atr_percent) AS min_atr_pct, SUM(s.risk_reward_ratio < 1) AS rr_below_1, SUM(pp.realized_pnl < 0) AS losers, SUM(pp.status = 'STOPPED') AS stopped, SUM(pp.realized_pnl) AS net_pnl FROM crypto_ai.paper_position pp JOIN crypto_ai.trade_signal s ON s.id = pp.signal_id WHERE pp.status IN ('CLOSED','STOPPED') GROUP BY s.symbol ORDER BY net_pnl LIMIT 40